    extrude(context, id + "tube", { "bodyType" : ExtendedToolBodyType.SURFACE, "surfaceEntities" : qOwnedByBody(qBodyType(qCreatedBy(id + "s1", EntityType.BODY), BodyType.WIRE), EntityType.EDGE), "endBound" : BoundingType.BLIND, "depth" : 30 * millimeter, "symmetric" : true });
    opPlane(context, id + "p1", { "plane" : plane(vector(0, 0, -8) * millimeter, vector(0, 0, 1), vector(1, 0, 0)), "width" : 100 * millimeter, "height" : 100 * millimeter });
    opPlane(context, id + "p2", { "plane" : plane(vector(0, 0, 9) * millimeter, vector(0.2, 0, 1), vector(1, 0, -0.2)), "width" : 100 * millimeter, "height" : 100 * millimeter });
    enclose(context, id + "enclose1", { "entities" : qUnion([qCreatedBy(id + "tube", EntityType.BODY), qCreatedBy(id + "p1", EntityType.BODY), qCreatedBy(id + "p2", EntityType.BODY)]) });
