// mutual-trim: two crossing sheets trimmed to each other
export function c023(context is Context, id is Id)
{
    const aSketch = newSketchOnPlane(context, id + "aSketch", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skLineSegment(aSketch, "line1", { "start" : vector(0, 0) * millimeter, "end" : vector(30, 10) * millimeter });
    skSolve(aSketch);
    extrude(context, id + "a", { "bodyType" : ExtendedToolBodyType.SURFACE, "surfaceEntities" : qOwnedByBody(qBodyType(qCreatedBy(id + "aSketch", EntityType.BODY), BodyType.WIRE), EntityType.EDGE), "endBound" : BoundingType.BLIND, "depth" : 20 * millimeter });
    const bSketch = newSketchOnPlane(context, id + "bSketch", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skLineSegment(bSketch, "line1", { "start" : vector(20, -5) * millimeter, "end" : vector(5, 15) * millimeter });
    skSolve(bSketch);
    extrude(context, id + "b", { "bodyType" : ExtendedToolBodyType.SURFACE, "surfaceEntities" : qOwnedByBody(qBodyType(qCreatedBy(id + "bSketch", EntityType.BODY), BodyType.WIRE), EntityType.EDGE), "endBound" : BoundingType.BLIND, "depth" : 20 * millimeter });
    mutualTrim(context, id + "trim1", { "body1" : qCreatedBy(id + "a", EntityType.BODY), "keepOtherSide1" : false, "body2" : qCreatedBy(id + "b", EntityType.BODY), "keepOtherSide2" : false, "merge" : true });
}

