// transform: move a block from one mate connector to another
export function c029(context is Context, id is Id)
{
    const baseSketch = newSketchOnPlane(context, id + "baseSketch", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skRectangle(baseSketch, "rect1", { "firstCorner" : vector(0, 0) * millimeter, "secondCorner" : vector(30, 20) * millimeter });
    skSolve(baseSketch);
    extrude(context, id + "base", { "entities" : qSketchRegion(id + "baseSketch"), "endBound" : BoundingType.BLIND, "depth" : 10 * millimeter });
    mateConnector(context, id + "from", { "originQuery" : qContainsPoint(qOwnedByBody(qBodyType(qCreatedBy(id + "base", EntityType.BODY), BodyType.SOLID), EntityType.FACE), vector(15, 10, 10) * millimeter), "entityInferenceType" : EntityInferenceType.CENTROID, "ownerPart" : qBodyType(qCreatedBy(id + "base", EntityType.BODY), BodyType.SOLID) });
    const targetSketch = newSketchOnPlane(context, id + "targetSketch", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skCircle(targetSketch, "circle1", { "center" : vector(60, 0) * millimeter, "radius" : 5 * millimeter });
    skSolve(targetSketch);
    extrude(context, id + "target", { "entities" : qSketchRegion(id + "targetSketch"), "endBound" : BoundingType.BLIND, "depth" : 12 * millimeter });
    mateConnector(context, id + "to", { "originQuery" : qContainsPoint(qOwnedByBody(qBodyType(qCreatedBy(id + "target", EntityType.BODY), BodyType.SOLID), EntityType.FACE), vector(60, 0, 12) * millimeter), "entityInferenceType" : EntityInferenceType.CENTROID, "ownerPart" : qBodyType(qCreatedBy(id + "target", EntityType.BODY), BodyType.SOLID) });
    transform(context, id + "transform1", { "entities" : qBodyType(qCreatedBy(id + "base", EntityType.BODY), BodyType.SOLID), "transformType" : TransformType.TRANSFORM_MATE_CONNECTORS, "baseConnector" : qBodyType(qCreatedBy(id + "from", EntityType.BODY), BodyType.MATE_CONNECTOR), "destinationConnector" : qBodyType(qCreatedBy(id + "to", EntityType.BODY), BodyType.MATE_CONNECTOR), "makeCopy" : false, "oppositeDirectionMateAxis" : false, "secondaryAxisType" : MateConnectorAxisType.PLUS_X });
}
